use anyhow::Result;use serde_json::json;use synara_core::{EntityId,Sequence};use synara_db::Database;use synara_events::Event;
#[derive(Debug)]pub enum Command{CreateProject{name:String,root_path:String},CreateThread{workspace_id:EntityId,title:Option<String>},SendMessage{thread_id:EntityId,content:String},StartTurn{thread_id:EntityId},StopTurn{thread_id:EntityId},ApproveTool{tool_call_id:EntityId,approved:bool}}
pub struct Orchestrator{pub db:Database,next_sequence:Sequence}
impl Orchestrator{pub fn new(db:Database)->Result<Self>{let mut n=0;for e in db.events_after(0)?{n=n.max(e.sequence)}Ok(Self{db,next_sequence:n+1})}pub fn dispatch(&mut self,c:Command)->Result<EntityId>{let(id,scope,typ,payload) = match c{Command::CreateProject{name,root_path}=>(EntityId::new(),"project","ProjectCreated",json!({"name":name,"root_path":root_path})),Command::CreateThread{workspace_id,title}=>(EntityId::new(),"thread","ThreadCreated",json!({"workspace_id":workspace_id,"title":title})),Command::SendMessage{thread_id,content}=>(EntityId::new(),"message","MessageCreated",json!({"thread_id":thread_id,"content":content})),Command::StartTurn{thread_id}=>(thread_id,"turn","TurnStarted",json!({"thread_id":thread_id})),Command::StopTurn{thread_id}=>(thread_id,"turn","TurnStopped",json!({"thread_id":thread_id})),Command::ApproveTool{tool_call_id,approved}=>(tool_call_id,"approval",if approved{"ToolApproved"}else{"ToolRejected"},json!({"tool_call_id":tool_call_id,"approved":approved}))};let e=Event::new(scope,id,typ,payload,1,self.next_sequence);self.db.append_event(&e)?;self.next_sequence+=1;Ok(id)}}
